def count_distinct_characters(string: str) -> int:
    seen = [False] * 256
    count = 0
    for char in string.lower():
        code = ord(char)
        if code < 256 and not seen[code]:
            seen[code] = True
            count += 1
    return count

def will_it_fly(q, w):
    weight = 0
    n = len(q)
    for i in range(n):
        weight += q[i]
        if weight > w:
            return False
        # Check symmetry against the corresponding index from the end
        if q[i] != q[n - 1 - i]:
            return False
    return True
